function letterCombinations(digits) {
  if (digits === "") return [];
  const keys = ["", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"];
  const result = [];
  const path = [];                            // the letters chosen so far
  const choose = (i) => {
    if (i === digits.length) {                // one letter per digit: a full combination
      result.push(path.join(""));
      return;
    }
    for (const letter of keys[digits[i]]) {
      path.push(letter);                      // choose
      choose(i + 1);                          // explore the rest
      path.pop();                             // un-choose, to try the next letter
    }
  };
  choose(0);
  return result;
}

static final String[] KEYS = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};

List<String> letterCombinations(String digits) {
    List<String> result = new ArrayList<>();
    if (digits.isEmpty()) return result;
    choose(digits, 0, new StringBuilder(), result);
    return result;
}

void choose(String digits, int i, StringBuilder path, List<String> result) {
    if (i == digits.length()) {                  // one letter per digit: a full combination
        result.add(path.toString());
        return;
    }
    for (char letter : KEYS[digits.charAt(i) - '0'].toCharArray()) {
        path.append(letter);                     // choose
        choose(digits, i + 1, path, result);     // explore the rest
        path.deleteCharAt(path.length() - 1);    // un-choose, to try the next letter
    }
}

